import 'package:flutter/material.dart'; import '../../../core/network/football_repository.dart';
class ExploreScreen extends StatefulWidget{const ExploreScreen({super.key});@override State<ExploreScreen> createState()=>_ExploreScreenState();}
class _ExploreScreenState extends State<ExploreScreen>{final c=TextEditingController();final repo=FootballRepository();Map<String,dynamic>? data;bool loading=false;Future<void> go()async{if(c.text.trim().length<2)return;setState(()=>loading=true);try{data=await repo.search(c.text.trim());}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Explore football')),body:ListView(padding:const EdgeInsets.all(18),children:[SearchBar(controller:c,hintText:'Team, player, competition or news',trailing:[IconButton(onPressed:go,icon:const Icon(Icons.search))],onSubmitted:(_)=>go()),if(loading)const Padding(padding:EdgeInsets.all(30),child:Center(child:CircularProgressIndicator())),if(data!=null)...data!.entries.map((e)=>Card(margin:const EdgeInsets.only(top:14),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.key.toUpperCase(),style:Theme.of(context).textTheme.labelLarge),const SizedBox(height:8),...((e.value as List?)??[]).take(8).map((x)=>ListTile(contentPadding:EdgeInsets.zero,title:Text((x['name']??x['title']??'').toString()),trailing:const Icon(Icons.chevron_right))) ]))))]));}}
